INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (964, 'LUT University Early Bird Discount and Progress Scholarships', 'LUT University', 'Finland', 'Tuition Waiver', 0, 'No separate scholarship application: the early bird discount is earned by accepting the study place and paying the discounted first-year fee within 21 days of the official admission email, and the progress scholarships are checked automatically after each academic year (credits on the transcript by 31 July). Master''s rolling admission for autumn 2027 runs 1 October 2026 - 31 March 2027 (currently open).', '2027-03-31', 'fixed', NULL, NULL, $j$["Bachelor's", "Master's"]$j$, $j$["English-taught bachelor\u2019s and two-year master\u2019s programmes at LUT University (technology, business, social and communication sciences; partner/joint programmes have separate scholarship policies)"]$j$, $j$["Students liable for tuition fees in Finland (non-EU/EEA/Swiss citizens without an exempting residence permit)"]$j$, NULL, NULL, false, true, $desc$LUT University prices its support as two automatic, flat-euro steps rather than a competition. At master's level (annual tuition fee €15,000 for non-EU/EEA students in all English-language programmes), every tuition-fee-paying student who accepts the study place and pays the remaining first-year fee of €10,000 within 21 days of the official admission email receives an Early Bird discount of €5,000; in the second academic year, a LUT scholarship of a further €5,000 follows automatically for students who complete at least 60 ECTS credits in the first year in accordance with their personal study plan (the credits must be on the transcript by 31 July and the second-year fee paid on time) - progress is checked automatically, so there is nothing to apply for. At bachelor's level (annual fee €12,000), the first year carries an early bird option rather than a scholarship, and continuing students of the 2026 intake receive automatic €3,000 scholarships for the second year after completing at least 60 ECTS in year one and for the third year after at least 120 ECTS across the first two years (credits are checked each August; a student attending only one semester in a year needs 30 ECTS instead of 60) - these bachelor's scholarships are tuition-fee discounts, not cash paid to the student. Earlier intakes had different values (50% scholarships for 2022-2025 bachelor's intakes), so the figures here are the current ones published for new admissions; partner and joint programmes run their own policies. LUT master's studies are applied to through rolling admission - for autumn 2027 the application window is 1 October 2026 to 31 March 2027 - and living costs (roughly €900-1,200 a month on LUT's campuses) are never part of the discounts.$desc$, $req$All of LUT's instruments here belong to tuition-fee-liable students (non-EU/EEA/Swiss citizens without a fee-exempting Finnish residence permit) in LUT's own English-taught programmes; joint/partner programmes follow their own scholarship policies. The early bird discount is conditional only on speed and payment: accept the place and pay the discounted first-year fee within 21 days of the official admission email. The progress scholarships need no application - LUT checks automatically whether at least 60 ECTS credits from the personal study plan stand on the transcript by 31 July (master's, for the €5,000 second-year scholarship, with the second-year fee also paid on time) or by August checks at bachelor's level (60 ECTS for the year-two €3,000, 120 ECTS for the year-three €3,000; 30 ECTS suffices after a single attended semester). Falling short of the credit pace means paying the full fee for that year. No grade-average condition and no scholarship-level IELTS figure are published, so min_gpa/min_ielts are not recorded. A non-EU/EEA application fee of €100 applies when applying to higher education in Finland. LUT University is not yet a university record in this catalogue, so no university link is attached.$req$, 'https://www.lut.fi/en/studies/apply-lut/applying-masters-programmes/rolling-admission-masters-studies/early-bird-discount-and-scholarships-masters-studies', 'https://www.lut.fi/en/studies/apply-lut/applying-masters-programmes/rolling-admission-masters-studies/early-bird-discount-and-scholarships-masters-studies', 'https://www.lut.fi/en/studies/apply-lut', 'annual', 'open', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 17) from LUT University's official pages fetched the same day - the master's programmes page (tuition fee €15,000/year for non-EU/EEA students; early bird discount of EUR 5,000 for the first year and a scholarship of EUR 5,000 for the second year; rolling admission 1 October 2026 - 31 March 2027; living expenses about €900-1,200/month), the 'Discounts for master's programmes' page (early bird: accept the place and pay the remaining €10,000 first-year fee within 21 days of the admission email; second-year LUT scholarship of €5,000 for at least 60 ECTS in year one under the personal study plan, credits on the transcript by 31 July, second-year fee paid on time, progress checked automatically; applies to LUT's two-year master's programmes, partner/joint programmes excepted), and the eLUT 'Scholarship for Bachelor's studies' page (bachelor's fee context with 2026-intake continuing-student scholarships of €3,000 for year two after at least 60 ECTS and €3,000 for year three after 120 ECTS, granted automatically, 30 ECTS if only one semester attended, credits checked in August, scholarships are fee discounts not cash payments; earlier intakes' 50% rates do not apply to new admissions). The Fulbright-LUT University Graduate Award on the same page is US-citizen-only and outside this record's identity. Award stored as NULL (EUR, 'year', 'variable') because the flat amounts differ by level and year (€5,000/€5,000 master's; €3,000/year bachelor's continuing), all itemised in funding_type; the bachelor's first-year early bird is described without an amount because the fetched pages confirm its availability but not its current euro value. deadline_date 2027-03-31 with status 'open' reflects the live master's rolling-admission window read on the fetched page (bachelor's applications run in the joint application; no date was invented for those). min_gpa/min_ielts NULL. university_id intentionally NULL: no LUT University record exists in the universities table yet - create/backlink recorded as a future task.$note$, NULL, NULL, 'EUR', 'year', 'variable', NULL, 'Master''s: €5,000 early bird discount in year 1 (accept + pay €10,000 balance within 21 days) and an automatic €5,000 scholarship in year 2 for at least 60 ECTS completed in year 1. Bachelor''s (2026 intake): automatic €3,000 discounts for years 2 and 3 on 60 / 120 ECTS progress; early bird option in year 1.', 'Discounts reduce the tuition fee (€15,000/year master''s, €12,000/year bachelor''s): a master''s student on pace pays €10,000 in each year; they are fee discounts, not cash, and never cover living expenses.', 'No scholarship-level IELTS figure; English requirements follow each programme''s admission rules.', $j$["For the early bird discount: accept the study place and pay the discounted first-year tuition fee within 21 days of the official admission email", "For progress scholarships: no application - automatic transcript check (at least 60 ECTS per academic year under the personal study plan, on record by 31 July at master's level; 60/120 ECTS August checks at bachelor's level) plus on-time fee payment", "Note: non-EU/EEA citizens pay a EUR 100 application fee when applying to higher education in Finland"]$j$, NULL, NULL, $json$[{"round": "Master's rolling admission, autumn 2027 entry", "opens": "2026-10-01", "deadline": "2027-03-31", "status": "open"}, {"pattern": "Annual: early bird discount for accepting and paying within 21 days of the admission email; progress scholarships then apply automatically from the second year onwards while the student completes at least 60 ECTS per year"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (965, 'Tampere University Tuition Fee Scholarships and Early Bird Offer', 'Tampere University', 'Finland', 'Tuition Waiver', 0, 'The tuition fee scholarship is applied for inside the Studyinfo.fi admission application during the application period (the decision is communicated together with the admission information). The early bird offer needs no application: accept the offered study place and pay the reduced first-year tuition fee within 21 days of receiving the admission information.', NULL, 'not_published', NULL, NULL, $j$["Bachelor's", "Master's"]$j$, $j$["English-taught bachelor's and master's programmes at Tampere University (scholarships are not awarded in all programmes; joint programmes may have differing fees)"]$j$, $j$["Students liable for tuition fees in Finland (non-EU/EEA/Swiss citizens without an exempting residence permit)"]$j$, NULL, NULL, false, true, $desc$Tampere University runs one of Finland's most selective admission scholarships: the Tampere University tuition fee scholarships awarded at admission cover 50% of the tuition fees for the whole programme duration, but they go to a very limited number of the best-performing applicants - in admission 2026 a total of nine scholarships were awarded across all bachelor's and master's programmes, and they are not awarded in all programmes. The scholarship is applied for as part of the Studyinfo.fi admission application and decided together with admission, on an overall academic assessment in which the application documents and a scholarship application letter (where the programme asks for one) can be decisive; the award then runs for the normative duration of the degree, counted in attending semesters (three years at bachelor's level, two years at master's), and plagiarism can cost the student the scholarship. Tampere's tuition fees for students admitted in 2027 are flat - €10,000 a year in all bachelor's programmes and €12,000 in all master's programmes - so the 50% scholarship is worth €5,000 or €6,000 a year respectively. For the realistic majority, two flat €2,000 instruments soften the first year: the early bird offer gives a €2,000 reduction on the first-year fee to any fee-paying student who was NOT awarded a tuition fee scholarship and who accepts the study place and pays the reduced first-year fee within 21 days of receiving the admission information (bachelor's applicants admitted from the waiting list need at least three weeks to remain before their acceptance deadline); and the Graduation Scholarship gives students who complete a bachelor's degree at Tampere within three academic years €2,000 off their first-year master's tuition fee at Tampere. Living costs are never covered and must be self-funded throughout.$desc$, $req$Applicants must be tuition-fee liable (non-EU/EEA/Swiss citizens without an exempting residence permit) applying to an English-taught bachelor's or master's programme at Tampere, and must apply for the scholarship within the Studyinfo admission application during the application period - scholarships exist only at admission, not in open-university-route or transfer applications. The 50% scholarships are awarded exceptionally sparingly (nine in total in the 2026 admissions) on overall academic assessment of the application; everyone else who pays fees can still use the €2,000 early bird offer (accept + pay within 21 days), which is expressly for non-scholarship holders. Scholarship duration is capped at the degree's normative time and counted by attending semesters; the Graduation Scholarship additionally requires completing the Tampere bachelor's degree within three academic years. No numeric GPA or IELTS threshold is set at scholarship level (admission criteria sit with the programmes), so min_gpa/min_ielts are not recorded. Tampere University is not yet a university record in this catalogue, so no university link is attached.$req$, 'https://www.tuni.fi/en/tau/financial-matters/tuition-fees-and-scholarships', 'https://www.tuni.fi/en/tau/financial-matters/tuition-fees-and-scholarships', 'https://www.tuni.fi/en/tau/financial-matters/tuition-fees-and-scholarships', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 17) from Tampere University's official 'Tuition Fees and Scholarships' page (2027-admissions edition) and its Student's Guide page 'Scholarships for fee-paying students admitted in 2026 or later', both fetched the same day (tuition fee scholarships at admission covering 50% of fees for the programme duration, highly selective - nine awarded in total across all bachelor's and master's programmes in admission 2026, not available in all programmes; applied for within the Studyinfo admission application, decided with admission on overall academic assessment incl. a possible scholarship letter; early bird offer of €2,000 off the first-year fee for fee-paying non-scholarship holders who accept and pay within 21 days, with the waiting-list caveat for bachelor's applicants; €2,000 Graduation Scholarship into a Tampere master's for those completing a Tampere bachelor's within three academic years; fees €10,000 bachelor's / €12,000 master's for 2027 admissions; scholarship duration capped at normative study time counted by attending semesters, awarded only at admission, plagiarism consequences; living costs never covered). Note the scheme changed for entrants from 2026 (the pre-2026 International Advancement Scholarship and the 2022-2024 Finland Scholarships belong to earlier cohorts and are not used). Award stored as NULL (EUR, 'year', 'variable'): the headline instrument is a percentage waiver and the two €2,000 reductions are one-off amounts, all itemised in funding_type. deadline_date NULL/'not_published' (the deadline is the annual Studyinfo application period); status 'upcoming'. min_gpa/min_ielts NULL. university_id intentionally NULL: no Tampere University record exists in the universities table yet - create/backlink recorded as a future task. This record extends the Finland coverage begun with records 742/405/504/505 and cannot be confused with them.$note$, NULL, NULL, 'EUR', 'year', 'variable', NULL, 'Tuition fee scholarships at admission covering 50% of the tuition fees for the programme duration (extremely selective - nine awarded in total in admission 2026); €2,000 early bird reduction on the first-year fee for non-holders paying within 21 days; €2,000 Graduation Scholarship into a Tampere master''s for on-time Tampere bachelor''s graduates', '50% of the tuition fee for scholarship holders for the normative duration (fees €10,000/year bachelor''s, €12,000/year master''s for 2027 admissions), i.e. €5,000-6,000/year; others get a flat €2,000 first-year reduction via the early bird offer. Living costs are not covered.', 'No scholarship-level IELTS figure; English requirements follow each programme''s admission rules.', $j$["Studyinfo.fi admission application with the scholarship request made inside it during the application period (including educational documents and a scholarship application letter where the programme requires one)", "For the early bird offer: accept the study place and pay the reduced first-year tuition fee within 21 days of receiving the admission information", "For the Graduation Scholarship: completion of a Tampere University bachelor's degree within three academic years"]$j$, NULL, NULL, $json$[{"edition": "Admission 2027 (fetched page)", "status": "upcoming"}, {"pattern": "Annual: scholarship requested within the Studyinfo admission application and decided with admission; early bird €2,000 if the place is accepted and the reduced first-year fee paid within 21 days of the admission information"}]$json$);

INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, deadline_date, deadline_type, deadline_range_start, deadline_range_end, degree_levels, eligible_majors, eligible_countries, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, source_url, application_url, recurrence, application_status, verification_status, source_reliability, is_active, last_verified_at, last_updated_at, notes, university_id, award_amount, award_currency, award_period, award_basis, living_allowance, funding_type, tuition_coverage, english_requirements, required_documents, expected_opening_period, expected_deadline_period, rounds) VALUES (966, 'Pekka Mattila Excellence Scholarship (Aalto University School of Business)', 'Aalto University School of Business', 'Finland', 'Partial Funding', 0, 'Applied for inside the Aalto master''s application itself during the master''s admissions application period (Studyinfo round for autumn entry - see the Marketing and International Management programme pages for dates); selected applicants are notified in the same week that Aalto admission results are published. There is no separate scholarship deadline.', NULL, 'not_published', NULL, NULL, $j$["Master's"]$j$, $j$["Aalto University School of Business: Master's Programme in Marketing; Master's Programme in International Management"]$j$, $j$["Students liable for tuition fees in Finland (non-EU/EEA/Swiss citizens without an exempting residence permit) - open regardless of age, nationality or gender"]$j$, NULL, NULL, false, true, $desc$The Pekka Mattila Excellence Scholarship is a named memorial scholarship at Aalto University School of Business, aimed at particularly talented tuition-fee-liable students admitted to the Master's Programme in Marketing or the Master's Programme in International Management. The award is a one-time relocation grant of €3,000, paid at the beginning of the degree programme - transferred during the recipient's first year of attendance to a Finnish or SEPA bank account after enrolment. Selection takes place during the admission process and rests on the academic evaluation of applicants according to the two programmes' evaluation criteria; applicants of any age, nationality or gender who are required to pay tuition fees may apply. The scholarship is applied for on the master's application form during the master's admissions application period (there is no separate form or later round), and selected applicants are notified in the same week in which Aalto's admission results are published. One important interaction: the Pekka Mattila Excellence Scholarship cannot be combined with the Aalto University Excellence Scholarship (the full tuition waiver catalogued as record 405) - an applicant may apply for both, but whoever is awarded the Aalto University Excellence Scholarship is no longer eligible for the Pekka Mattila grant. Set against the School of Business master's tuition fee of €15,000 a year, the €3,000 grant is a relocation contribution rather than degree financing, and the record presents it on exactly those terms.$desc$, $req$Applicants must be required to pay tuition fees (non-EU/EEA/Swiss citizenship without a fee-exempting Finnish residence permit) and be applying to the Aalto School of Business Master's Programme in Marketing or Master's Programme in International Management; the scholarship must be requested on the master's application form during the application period. Selection is merit-based, decided within admissions on the programmes' published evaluation criteria, and the award is incompatible with holding the Aalto University Excellence Scholarship (record 405) at the same time. The €3,000 relocation grant is paid once, in the first year after enrolment, to a Finnish or SEPA bank account. No scholarship-level GPA or IELTS figure is published (admission criteria, including English requirements, are set on the programme pages), so min_gpa/min_ielts are not recorded.$req$, 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', 'annual', 'upcoming', 'verified', 10, true, now(), now(), $note$ADDED 2026-10-27 (enrichment batch 17) from the 'Pekka Mattila Excellence Scholarship' section of Aalto University's official 'Scholarships and Tuition Fees' page fetched the same day (in memory of Pekka Mattila; merit-based scholarships for particularly talented, tuition-fee-liable students admitted to the School of Business Master's Programme in Marketing and Master's Programme in International Management; €3,000 relocation grant paid at the beginning of the programme - transferred during the first year of attendance to Finnish/SEPA accounts after enrolment; open regardless of age, nationality or gender; selection during admission on the programmes' evaluation criteria; applied for on the master's application form during the admissions period; notified in the same week as the admission results; cannot be combined with the Aalto University Excellence Scholarship, though both may be applied for). This scheme was spotted while rewriting record 405 in cleanup pass 110 and is catalogued here as the separate named award it is. Award stored as 3000 EUR/'one_time'/fixed. deadline_date NULL/'not_published' (the only deadline is the master's application period itself); status 'upcoming' ahead of the autumn-entry admissions round. min_gpa/min_ielts NULL. university_id set to the existing Aalto University record (103), a university_scholarships row added, and the record linked to the already-verified source 2476 (the Aalto scholarships page).$note$, 103, 3000, 'EUR', 'one_time', 'fixed', NULL, 'One-time €3,000 relocation grant paid at the beginning of the master''s programme (after enrolment) to particularly talented tuition-fee-liable admits in Marketing or International Management', 'The scholarship does not reduce the tuition fee itself (School of Business master''s fee €15,000/year) - it is a €3,000 cash relocation grant; it also cannot be combined with the Aalto University Excellence Scholarship full waiver (record 405).', 'No scholarship-level IELTS figure; English requirements follow the Marketing / International Management master''s admission criteria.', $j$["Master's application to the Aalto School of Business Marketing or International Management programme with the scholarship option taken up on the application form during the application period", "Tuition-fee-liable status in Finland (non-EU/EEA/Swiss citizenship without an exempting residence permit)"]$j$, NULL, NULL, $json$[{"pattern": "Annual, inside Aalto master's admissions: apply on the master's application form during the application period for autumn entry; decisions notified in the same week as the admission results; grant paid once after enrolment"}]$json$);

INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES
(3100, 'https://www.lut.fi/en/studies/apply-lut/applying-masters-programmes/rolling-admission-masters-studies/early-bird-discount-and-scholarships-masters-studies', 'Discounts for master''s programmes - LUT University (official)', 'lut.fi', 'scholarship', now(), true, true, now()),
(3101, 'https://www.tuni.fi/en/tau/financial-matters/tuition-fees-and-scholarships', 'Tuition Fees and Scholarships - Tampere University (official)', 'tuni.fi', 'scholarship', now(), true, true, now());

INSERT INTO scholarship_sources (scholarship_id, source_id) VALUES (964, 3100), (965, 3101), (966, 2476);

INSERT INTO university_scholarships (id, university_id, scholarship_id, scholarship_name, availability_status, funding_type, max_scholarship, covers_tuition, covers_living_expenses, valued_aspect, eligibility_notes, official_url, source_url, verification_status, last_verified_at) VALUES
(696, 103, 966, 'Pekka Mattila Excellence Scholarship', 'available', 'Partial Funding', 'One-time €3,000 relocation grant paid at the start of the master''s programme', false, true, 'Particularly talented applicants (admissions academic evaluation)', 'For tuition-fee-liable applicants to the School of Business Master''s Programme in Marketing or International Management (any age/nationality/gender). Apply on the master''s application form during the application period; selection on the programmes'' evaluation criteria; notified in the same week as admission results. Cannot be combined with the Aalto University Excellence Scholarship (full waiver) - applying for both is allowed, but winning the waiver cancels eligibility for this grant. Paid once in the first year after enrolment to a Finnish/SEPA account.', 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', 'https://www.aalto.fi/en/admission-services/scholarships-and-tuition-fees', 'verified', now());

SELECT setval('scholarships_id_seq', GREATEST((SELECT MAX(id) FROM scholarships), 966), true);
SELECT setval('sources_id_seq', GREATEST((SELECT MAX(id) FROM sources), 3101), true);
SELECT setval('university_scholarships_id_seq', GREATEST((SELECT MAX(id) FROM university_scholarships), 696), true);
